// Material 3 theming: default scheme from the exported JSON, other seeds generated by Material Color Utilities.
import { buildScheme } from '../vendor/mcu.js';
import { DEFAULT_SEED, DEFAULT_SCHEMES } from './theme-default.js';

export { DEFAULT_SEED };

/** Material Design color palette (500 shades) used as theme color presets. */
export const PRESETS = [
  { id: 'default', seed: DEFAULT_SEED, key: 'cDefault' },
  { id: 'red', seed: '#F44336', key: 'c_red' },
  { id: 'pink', seed: '#E91E63', key: 'c_pink' },
  { id: 'purple', seed: '#9C27B0', key: 'c_purple' },
  { id: 'deepPurple', seed: '#673AB7', key: 'c_deepPurple' },
  { id: 'indigo', seed: '#3F51B5', key: 'c_indigo' },
  { id: 'blue', seed: '#2196F3', key: 'c_blue' },
  { id: 'lightBlue', seed: '#03A9F4', key: 'c_lightBlue' },
  { id: 'cyan', seed: '#00BCD4', key: 'c_cyan' },
  { id: 'teal', seed: '#009688', key: 'c_teal' },
  { id: 'green', seed: '#4CAF50', key: 'c_green' },
  { id: 'lightGreen', seed: '#8BC34A', key: 'c_lightGreen' },
  { id: 'lime', seed: '#CDDC39', key: 'c_lime' },
  { id: 'yellow', seed: '#FFEB3B', key: 'c_yellow' },
  { id: 'amber', seed: '#FFC107', key: 'c_amber' },
  { id: 'orange', seed: '#FF9800', key: 'c_orange' },
  { id: 'deepOrange', seed: '#FF5722', key: 'c_deepOrange' },
  { id: 'brown', seed: '#795548', key: 'c_brown' },
  { id: 'blueGrey', seed: '#607D8B', key: 'c_blueGrey' },
];

const cache = new Map();
export function schemeFor(seed, dark) {
  const s = seed.toUpperCase();
  const key = s + (dark ? ':d' : ':l');
  if (!cache.has(key)) {
    cache.set(key, s === DEFAULT_SEED ? DEFAULT_SCHEMES[dark ? 'dark' : 'light'] : buildScheme(s, dark));
  }
  return cache.get(key);
}

const kebab = (s) => s.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());

export function applyScheme(seed, dark) {
  const root = document.documentElement;
  const scheme = schemeFor(seed, dark);
  for (const [role, value] of Object.entries(scheme)) root.style.setProperty('--md-' + kebab(role), value);
  root.style.colorScheme = dark ? 'dark' : 'light';
  root.dataset.mode = dark ? 'dark' : 'light';
}
